import { auditPairings, contrastRatio } from './contrast.ts';
import { colors, fontFamilies, motion, radius, space, typeScale } from './tokens.ts';

const GENERATED =
  'GENERATED by `pnpm --filter @jom/ui generate` from packages/ui/src — do not edit.';

export function renderTokensCss(): string {
  const lines: string[] = [`/* ${GENERATED} */`, ':root {'];
  for (const [name, value] of Object.entries(colors)) lines.push(`  --${name}: ${value};`);
  lines.push('');
  for (const [name, value] of Object.entries(typeScale)) lines.push(`  --t-${name}: ${value};`);
  lines.push('');
  space.forEach((px, i) => lines.push(`  --space-${i + 1}: ${px}px;`));
  lines.push('');
  for (const [name, value] of Object.entries(radius)) lines.push(`  --radius-${name}: ${value};`);
  lines.push('  --rule: 1px solid var(--ink);');
  lines.push('  --rule-dashed: 1px dashed var(--paper-shadow);');
  lines.push('');
  for (const [name, value] of Object.entries(fontFamilies)) {
    lines.push(`  --family-${name}: ${value};`);
  }
  lines.push('');
  for (const [name, value] of Object.entries(motion)) lines.push(`  --motion-${name}: ${value};`);
  lines.push('}', '');
  return lines.join('\n');
}

export function renderContrastReport(): string {
  const results = auditPairings();
  const rows = results.map(
    (r) =>
      `| \`--${r.fg}\` | \`--${r.bg}\` | ${r.ratio.toFixed(2)}:1 | ${r.use} | ${
        r.use === 'never-text' ? '< 4.5 (forbidden)' : `≥ ${r.required}`
      } | ${r.pass ? 'pass' : '**FAIL**'} | ${r.where} |`,
  );
  const docClaims = [
    ['ink', 'paper', '11.2'],
    ['marigold', 'carbon', '9.1'],
  ] as const;
  const claimRows = docClaims.map(
    ([fg, bg, claimed]) =>
      `| \`--${fg}\` on \`--${bg}\` | ${claimed}:1 | ${contrastRatio(colors[fg], colors[bg]).toFixed(2)}:1 |`,
  );

  return [
    '# Contrast audit',
    '',
    `<!-- ${GENERATED} -->`,
    '',
    'Every approved token pairing (DESIGNING.md §2.1, §5), computed with the WCAG 2.x',
    'relative-luminance formula. `packages/ui/test/contrast.test.ts` fails CI if any row fails.',
    '',
    '| Foreground | Background | Ratio | Use | Required | Result | Where |',
    '|---|---|---|---|---|---|---|',
    ...rows,
    '',
    '## Findings',
    '',
    '- `--red-pen` on `--paper` is below 4.5:1, so red-pen is **large text (≥24px) or',
    '  non-text only** on paper. The 61px death number qualifies; body-size red text does not.',
    '- DESIGNING.md states two ratios slightly differently from the computed values (both',
    '  still pass):',
    '',
    '| Pairing | DESIGNING.md says | Computed |',
    '|---|---|---|',
    ...claimRows,
    '',
    '## Not covered by this audit',
    '',
    '- Colour-blind check of `--red-pen` vs `--marigold` on `--carbon` under deuteranopia and',
    '  protanopia (DESIGNING.md §5). Needs a manual simulation pass once real sprites exist.',
    '',
  ].join('\n');
}
